1	package strategy
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"log/slog"
9		"os"
10		"os/exec"
11		"path/filepath"
12		"strings"
13		"sync"
14		"time"
15	
16		"github.com/entireio/cli/cmd/entire/cli/checkpoint"
17		"github.com/entireio/cli/cmd/entire/cli/logging"
18	
19		"github.com/go-git/go-git/v6"
20		"github.com/go-git/go-git/v6/plumbing"
21		"github.com/go-git/go-git/v6/plumbing/object"
22		"github.com/go-git/go-git/v6/utils/merkletrie"
23	)
24	
25	// disconnectedOnce ensures the disconnection warning runs at most once per process.
26	var disconnectedOnce sync.Once //nolint:gochecknoglobals // intentional per-process gate
27	
28	// IsMetadataDisconnected checks whether the local primary metadata ref and
29	// the provided fetched or remote-tracking ref exist but share no common
30	// ancestor.
31	func IsMetadataDisconnected(ctx context.Context, repo *git.Repository, remoteRefName plumbing.ReferenceName) (bool, error) {
32		refs := checkpoint.ResolveCommittedRefs(ctx)
33		localRef, err := repo.Reference(refs.Primary, true)
34		if errors.Is(err, plumbing.ErrReferenceNotFound) {
35			return false, nil
36		}
37		if err != nil {
38			return false, fmt.Errorf("failed to check local primary metadata ref: %w", err)
39		}
40	
41		remoteRef, err := repo.Reference(remoteRefName, true)
42		if errors.Is(err, plumbing.ErrReferenceNotFound) {
43			return false, nil
44		}
45		if err != nil {
46			return false, fmt.Errorf("failed to check remote metadata ref: %w", err)
47		}
48	
49		if localRef.Hash() == remoteRef.Hash() {
50			return false, nil
51		}
52	
53		repoPath, err := getRepoPath(repo)
54		if err != nil {
55			return false, err
56		}
57	
58		return metadataDisconnected(ctx, repo, repoPath, localRef.Hash().String(), remoteRef.Hash().String())
59	}
60	
61	// WarnIfMetadataDisconnected checks (once per process) whether the metadata
62	// branch is disconnected and prints a warning to stderr if so.
63	// It does NOT fix the problem — users are directed to 'entire doctor'.
64	//
65	// Uses sync.Once, so a transient failure on the first call permanently suppresses
66	// the warning. This is acceptable because the check is advisory only and
67	// 'entire doctor' is the authoritative repair path.
68	func WarnIfMetadataDisconnected() {
69		disconnectedOnce.Do(func() {
70			ctx := context.Background()
71			repo, err := OpenRepository(ctx)
72			if err != nil {
73				logging.Debug(ctx, "metadata disconnection check: could not open repository",
74					slog.String("error", err.Error()))
75				return
76			}
77			defer repo.Close()
78			refs := checkpoint.ResolveCommittedRefs(ctx)
79			if !refs.PrimaryFetchableFromOrigin() {
80				return // origin doesn't track Primary; nothing to disconnect from
81			}
82			disconnected, err := IsMetadataDisconnected(ctx, repo, plumbing.NewRemoteReferenceName("origin", refs.Primary.Short()))
83			if err != nil {
84				logging.Debug(ctx, "metadata disconnection check failed",
85					slog.String("error", err.Error()))
86				return
87			}
88			if !disconnected {
89				return
90			}
91			fmt.Fprintln(os.Stderr, "[entire] Warning: Local and remote session metadata branches are disconnected.")
92			fmt.Fprintln(os.Stderr, "[entire] Some checkpoints from remote may not be visible. Run 'entire doctor' to fix.")
93		})
94	}
95	
96	// ReconcileDisconnectedMetadataRef detects and repairs disconnected local/remote
97	// metadata refs. Disconnected means no common ancestor — genuinely caused by the
98	// empty-orphan bug. Diverged (shared ancestor) is normal and handled by the push
99	// path. The disconnection check is shallow-aware (see metadataDisconnected): on a
100	// shallow clone a merge-base miss is suppressed rather than trusted, so this
101	// no-ops instead of attempting a doomed full-history cherry-pick.
102	//
103	// Repair strategy: cherry-pick local commits onto remote tip, preserving all data.
104	// Checkpoint shards use unique paths (<id[:2]>/<id[2:]>/), so cherry-picks always
105	// apply cleanly.
106	//
107	// Progress messages are written to w (typically os.Stderr for hooks or
108	// cmd.ErrOrStderr() for commands).
109	// The remote ref can be either a remote-tracking ref or a temporary fetched ref.
110	func ReconcileDisconnectedMetadataRef(
111		ctx context.Context,
112		repo *git.Repository,
113		localRefName plumbing.ReferenceName,
114		remoteRefName plumbing.ReferenceName,
115		w io.Writer,
116	) error {
117		refs := checkpoint.ResolveCommittedRefs(ctx)
118		advance := func(hash plumbing.Hash) error {
119			return AdvanceLocalRef(ctx, repo, refs, localRefName, hash)
120		}
121	
122		// Check local ref
123		localRef, err := repo.Reference(localRefName, true)
124		if errors.Is(err, plumbing.ErrReferenceNotFound) {
125			return nil // No local ref — nothing to reconcile
126		}
127		if err != nil {
128			return fmt.Errorf("failed to check local metadata ref: %w", err)
129		}
130	
131		// Check remote-tracking or fetched ref
132		remoteRef, err := repo.Reference(remoteRefName, true)
133		if errors.Is(err, plumbing.ErrReferenceNotFound) {
134			return nil // No remote ref — nothing to reconcile
135		}
136		if err != nil {
137			return fmt.Errorf("failed to check remote metadata ref: %w", err)
138		}
139	
140		localHash := localRef.Hash()
141		remoteHash := remoteRef.Hash()
142	
143		// Same hash — nothing to do
144		if localHash == remoteHash {
145			return nil
146		}
147	
148		// Check if disconnected using git merge-base
149		repoPath, err := getRepoPath(repo)
150		if err != nil {
151			return err
152		}
153	
154		disconnected, err := metadataDisconnected(ctx, repo, repoPath, localHash.String(), remoteHash.String())
155		if err != nil {
156			return fmt.Errorf("failed to check metadata ref ancestry: %w", err)
157		}
158		if !disconnected {
159			// Shared ancestry (diverged or ancestor) — not our problem
160			return nil
161		}
162	
163		// Disconnected — cherry-pick local commits onto remote tip
164		fmt.Fprintln(w, "[entire] Detected disconnected session metadata (local and remote share no common ancestor)")
165	
166		shallow, err := loadShallowHashes(ctx, repoPath)
167		if err != nil {
168			return fmt.Errorf("failed to load shallow boundaries: %w", err)
169		}
170	
171		// Collect local commits oldest-first
172		localCommits, err := collectCommitChain(repo, localHash, shallow)
173		if err != nil {
174			return fmt.Errorf("failed to collect local commits: %w", err)
175		}
176	
177		// Filter out empty-tree commits (the orphan bug commit)
178		var dataCommits []*object.Commit
179		for _, c := range localCommits {
180			tree, treeErr := c.Tree()
181			if treeErr != nil {
182				return fmt.Errorf("failed to read tree for commit %s: %w", c.Hash.String()[:7], treeErr)
183			}
184			if len(tree.Entries) > 0 {
185				dataCommits = append(dataCommits, c)
186			}
187		}
188	
189		if len(dataCommits) == 0 {
190			// Local only had empty orphan — just point to remote
191			if err := advance(remoteHash); err != nil {
192				return fmt.Errorf("failed to reset metadata ref to remote: %w", err)
193			}
194			fmt.Fprintln(w, "[entire] Done — local had no checkpoint data, reset to remote")
195			return nil
196		}
197	
198		fmt.Fprintf(w, "[entire] Cherry-picking %d local checkpoint(s) onto remote...\n", len(dataCommits))
199	
200		newTip, err := cherryPickOnto(ctx, repo, remoteHash, dataCommits, shallow)
201		if err != nil {
202			return fmt.Errorf("failed to cherry-pick local commits onto remote: %w", err)
203		}
204	
205		if err := advance(newTip); err != nil {
206			return fmt.Errorf("failed to update metadata ref: %w", err)
207		}
208	
209		fmt.Fprintln(w, "[entire] Done — all local and remote checkpoints preserved")
210		return nil
211	}
212	
213	// metadataDisconnected reports whether the local and remote metadata commits
214	// share no common ancestor, accounting for shallow clones.
215	//
216	// A bare `git merge-base` miss is NOT sufficient evidence of disconnection when
217	// the metadata history is shallow: the real common ancestor can live below the
218	// shallow boundary, where git has no objects, so merge-base reports a false "no
219	// common ancestor". Checkpoint metadata branches are routinely shallow —
220	// resume/explain fetch the tip with --depth=1 and nothing deepens them again
221	// (see FetchMetadataTreeOnly) — so trusting that miss marks an ordinary
222	// diverged-but-behind branch as disconnected and triggers a doomed full-history
223	// reconcile (collectCommitChain blows MaxCommitTraversalDepth on a deep team
224	// branch).
225	//
226	// We therefore only treat a merge-base miss as a genuine disconnection when the
227	// metadata history does not reach a shallow boundary. The check is keyed on the
228	// metadata commits specifically (not merely "is the repo shallow"), so a
229	// genuine disconnection on a repo that is shallow only for an unrelated
230	// source-tree branch is still reported. When the metadata history is
231	// shallow-bounded the verdict is suppressed (refs reported connected) and
232	// 'entire doctor' is the path that deepens the branch and re-checks.
233	func metadataDisconnected(ctx context.Context, repo *git.Repository, repoPath, localHash, remoteHash string) (bool, error) {
234		disconnected, err := isDisconnected(ctx, repoPath, localHash, remoteHash)
235		if err != nil {
236			return false, err
237		}
238		if !disconnected {
239			return false, nil
240		}
241		bounded, err := hasReachableShallowBoundary(ctx, repo, repoPath, localHash, remoteHash)
242		if err != nil {
243			return false, err
244		}
245		if bounded {
246			logging.Debug(ctx, "merge-base reports no common ancestor but metadata history reaches a "+
247				"shallow boundary; treating refs as connected (run 'entire doctor' to deepen and re-check)",
248				slog.String("local", localHash),
249				slog.String("remote", remoteHash))
250			return false, nil
251		}
252		return true, nil
253	}
254	
255	// MetadataHistoryShallowBounded reports whether the local primary metadata ref
256	// or its origin remote-tracking ref has a shallow boundary in its ancestry —
257	// i.e. whether deepening the metadata branch could change a merge-base result.
258	//
259	// 'entire doctor' uses this to decide whether to deepen before the disconnection
260	// check, so it never issues a (potentially large) deepen for a shallow boundary
261	// that belongs to an unrelated branch such as a shallow source-tree clone.
262	func MetadataHistoryShallowBounded(ctx context.Context, repo *git.Repository) (bool, error) {
263		repoPath, err := getRepoPath(repo)
264		if err != nil {
265			return false, err
266		}
267		refs := checkpoint.ResolveCommittedRefs(ctx)
268	
269		var hashes []string
270		addRef := func(name plumbing.ReferenceName) {
271			if ref, refErr := repo.Reference(name, true); refErr == nil {
272				hashes = append(hashes, ref.Hash().String())
273			}
274		}
275		addRef(refs.Primary)
276		if refs.PrimaryFetchableFromOrigin() {
277			addRef(plumbing.NewRemoteReferenceName("origin", refs.Primary.Short()))
278		}
279		if len(hashes) == 0 {
280			return false, nil
281		}
282		return hasReachableShallowBoundary(ctx, repo, repoPath, hashes...)
283	}
284	
285	// isDisconnected checks if two commits have no common ancestor using git merge-base.
286	// Returns (true, nil) if disconnected, (false, nil) if they share ancestry,
287	// or (false, error) if git merge-base failed for another reason.
288	//
289	// git merge-base exit codes:
290	//   - 0: common ancestor found (shared ancestry)
291	//   - 1: no common ancestor (disconnected)
292	//   - 128+: error (corrupt repo, invalid hash, etc.)
293	func isDisconnected(ctx context.Context, repoPath, hashA, hashB string) (bool, error) {
294		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
295		defer cancel()
296		cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
297		cmd.Dir = repoPath
298		if err := cmd.Run(); err != nil {
299			var exitErr *exec.ExitError
300			if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
301				return true, nil // No common ancestor — disconnected
302			}
303			return false, fmt.Errorf("git merge-base failed: %w", err)
304		}
305		return false, nil // Shared ancestry
306	}
307	
308	// collectCommitChain walks from tip to root following first parent, returns oldest-first.
309	// Commits listed in shallow are treated as roots — the walk stops at them without
310	// traversing into their parents. go-git's repo.CommitObject().ParentHashes does not
311	// consult .git/shallow on its own, so without this check the walk would stroll past
312	// shallow boundaries into stale objects left in the pack (e.g., when the remote
313	// branch has been rebuilt since the last full fetch), producing a phantom chain of
314	// commits that no longer represent the actual checkpoint history.
315	func collectCommitChain(repo *git.Repository, tip plumbing.Hash, shallow map[plumbing.Hash]bool) ([]*object.Commit, error) {
316		var chain []*object.Commit
317		current := tip
318	
319		reachedRoot := false
320		for range MaxCommitTraversalDepth {
321			commit, err := repo.CommitObject(current)
322			if err != nil {
323				return nil, fmt.Errorf("failed to get commit %s: %w", current, err)
324			}
325			chain = append(chain, commit)
326	
327			if len(commit.ParentHashes) == 0 {
328				reachedRoot = true
329				break
330			}
331			if shallow[current] {
332				// Shallow boundary — treat as a root.
333				reachedRoot = true
334				break
335			}
336			current = commit.ParentHashes[0]
337		}
338	
339		if !reachedRoot {
340			return nil, fmt.Errorf("commit chain exceeded %d commits without reaching root; aborting reconciliation", MaxCommitTraversalDepth)
341		}
342	
343		// Reverse to oldest-first
344		for i, j := 0, len(chain)-1; i < j; i, j = i+1, j-1 {
345			chain[i], chain[j] = chain[j], chain[i]
346		}
347	
348		return chain, nil
349	}
350	
351	// loadShallowHashes returns the commit hashes listed in the repository's
352	// shallow file, or an empty map if the repository is not shallow.
353	func loadShallowHashes(ctx context.Context, repoPath string) (map[plumbing.Hash]bool, error) {
354		cmd := exec.CommandContext(ctx, "git", "rev-parse", "--git-common-dir")
355		cmd.Dir = repoPath
356		out, err := cmd.Output()
357		if err != nil {
358			return nil, fmt.Errorf("git rev-parse --git-common-dir: %w", err)
359		}
360		gitDir := strings.TrimSpace(string(out))
361		if !filepath.IsAbs(gitDir) {
362			gitDir = filepath.Join(repoPath, gitDir)
363		}
364		// Path is constructed from git's own --git-common-dir output, not user input.
365		data, err := os.ReadFile(filepath.Join(gitDir, "shallow")) //nolint:gosec // see comment above
366		if err != nil {
367			if errors.Is(err, os.ErrNotExist) {
368				return map[plumbing.Hash]bool{}, nil
369			}
370			return nil, fmt.Errorf("read shallow file: %w", err)
371		}
372		set := map[plumbing.Hash]bool{}
373		for _, line := range strings.Split(string(data), "\n") {
374			line = strings.TrimSpace(line)
375			if line == "" {
376				continue
377			}
378			set[plumbing.NewHash(line)] = true
379		}
380		return set, nil
381	}
382	
383	// cherryPickOnto applies each commit's delta onto base, building a linear chain.
384	// For each commit, it computes the full diff from its parent (additions, modifications,
385	// and deletions), then applies that delta onto the current tip's tree.
386	//
387	// Commits listed in shallow are treated as roots: their delta is computed against
388	// an empty tree rather than against their (past-the-boundary) parent. Without this,
389	// a shallow-boundary commit would be diffed against a stale parent tree whose
390	// objects live in the local pack but no longer represent the actual checkpoint
391	// history — producing nonsense changes when replayed onto the remote tip.
392	func cherryPickOnto(ctx context.Context, repo *git.Repository, base plumbing.Hash, commits []*object.Commit, shallow map[plumbing.Hash]bool) (plumbing.Hash, error) {
393		currentTip := base
394	
395		for _, commit := range commits {
396			changes, err := treeChangesForCherryPick(ctx, repo, commit, shallow)
397			if err != nil {
398				return plumbing.ZeroHash, err
399			}
400			if len(changes) == 0 {
401				continue // Skip no-op commits
402			}
403	
404			tipCommit, err := repo.CommitObject(currentTip)
405			if err != nil {
406				return plumbing.ZeroHash, fmt.Errorf("failed to get tip commit: %w", err)
407			}
408	
409			mergedTreeHash, err := checkpoint.ApplyTreeChanges(ctx, repo, tipCommit.TreeHash, changes)
410			if err != nil {
411				return plumbing.ZeroHash, fmt.Errorf("failed to apply cherry-pick changes: %w", err)
412			}
413	
414			// Create new commit on top of current tip, preserving original message/author
415			newHash, err := createCherryPickCommit(ctx, repo, mergedTreeHash, currentTip, commit)
416			if err != nil {
417				return plumbing.ZeroHash, fmt.Errorf("failed to create cherry-pick commit: %w", err)
418			}
419	
420			currentTip = newHash
421		}
422	
423		return currentTip, nil
424	}
425	
426	func treeChangesForCherryPick(ctx context.Context, repo *git.Repository, commit *object.Commit, shallow map[plumbing.Hash]bool) ([]checkpoint.TreeChange, error) {
427		commitTree, err := commit.Tree()
428		if err != nil {
429			return nil, fmt.Errorf("failed to get tree for commit %s: %w", commit.Hash, err)
430		}
431	
432		var parentTree *object.Tree
433		// Shallow-boundary commits are treated as roots — see cherryPickOnto for why.
434		if len(commit.ParentHashes) > 0 && !shallow[commit.Hash] {
435			parentCommit, pErr := repo.CommitObject(commit.ParentHashes[0])
436			if pErr != nil {
437				return nil, fmt.Errorf("failed to get parent commit %s: %w", commit.ParentHashes[0], pErr)
438			}
439			parentTree, err = parentCommit.Tree()
440			if err != nil {
441				return nil, fmt.Errorf("failed to get parent tree for commit %s: %w", commit.ParentHashes[0], err)
442			}
443		}
444	
445		changes, err := object.DiffTreeContext(ctx, parentTree, commitTree)
446		if err != nil {
447			return nil, fmt.Errorf("failed to diff commit %s against parent: %w", commit.Hash, err)
448		}
449	
450		treeChanges := make([]checkpoint.TreeChange, 0, len(changes))
451		for _, change := range changes {
452			treeChange, changeErr := changeToTreeChange(change)
453			if changeErr != nil {
454				return nil, fmt.Errorf("failed to convert change in commit %s: %w", commit.Hash, changeErr)
455			}
456			treeChanges = append(treeChanges, treeChange)
457		}
458		return treeChanges, nil
459	}
460	
461	func changeToTreeChange(change *object.Change) (checkpoint.TreeChange, error) {
462		action, err := change.Action()
463		if err != nil {
464			return checkpoint.TreeChange{}, fmt.Errorf("change action: %w", err)
465		}
466	
467		switch action {
468		case merkletrie.Insert, merkletrie.Modify:
469			entry := change.To.TreeEntry
470			return checkpoint.TreeChange{
471				Path: change.To.Name,
472				Entry: &object.TreeEntry{
473					Name: entry.Name,
474					Mode: entry.Mode,
475					Hash: entry.Hash,
476				},
477			}, nil
478		case merkletrie.Delete:
479			return checkpoint.TreeChange{Path: change.From.Name}, nil
480		default:
481			return checkpoint.TreeChange{}, fmt.Errorf("unsupported action %s", action)
482		}
483	}
484	
485	// createCherryPickCommit creates a new commit on top of parent, preserving the
486	// original commit's message and author.
487	func createCherryPickCommit(ctx context.Context, repo *git.Repository, treeHash, parent plumbing.Hash, original *object.Commit) (plumbing.Hash, error) {
488		committerName, committerEmail := GetGitAuthorFromRepo(repo)
489		now := time.Now()
490	
491		commit := &object.Commit{
492			TreeHash:     treeHash,
493			ParentHashes: []plumbing.Hash{parent},
494			Author:       original.Author,
495			Committer: object.Signature{
496				Name:  committerName,
497				Email: committerEmail,
498				When:  now,
499			},
500			Message: original.Message,
501		}
502	
503		checkpoint.SignCommitBestEffort(ctx, commit)
504	
505		obj := repo.Storer.NewEncodedObject()
506		if err := commit.Encode(obj); err != nil {
507			return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
508		}
509	
510		hash, err := repo.Storer.SetEncodedObject(obj)
511		if err != nil {
512			return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
513		}
514	
515		return hash, nil
516	}
517	
518	// getRepoPath returns the filesystem path for the repository's worktree.
519	func getRepoPath(repo *git.Repository) (string, error) {
520		wt, err := repo.Worktree()
521		if err != nil {
522			return "", fmt.Errorf("failed to get worktree: %w", err)
523		}
