100	// the tmp ref. The cleanup is deferred so the tmp ref is reaped even when
101	// the advance fails.
102	//
103	// label is a short human-readable name used in error messages. Typical use:
104	//
105	//	// fetch with refspec "+<src>:<tmpRefName>"
106	//	refs := checkpoint.ResolveCommittedRefs(ctx)
107	//	return PromoteTmpRefSafely(ctx, tmpRefName, refs.Primary, refs.Primary.Short())
108	func PromoteTmpRefSafely(ctx context.Context, tmpRefName, destRefName plumbing.ReferenceName, label string) error {
109		repo, err := OpenRepository(ctx)
110		if err != nil {
111			return fmt.Errorf("failed to open repository for %s promote: %w", label, err)
112		}
113		defer repo.Close()
114		defer func() { _ = repo.Storer.RemoveReference(tmpRefName) }() //nolint:errcheck // cleanup is best-effort
115	
116		tmpRef, err := repo.Reference(tmpRefName, true)
117		if err != nil {
118			return fmt.Errorf("%s not found after fetch (tmp ref %s missing): %w", label, tmpRefName, err)
119		}
120		if err := SafelyAdvanceLocalRef(ctx, repo, destRefName, tmpRef.Hash()); err != nil {
121			return fmt.Errorf("failed to advance local %s: %w", label, err)
122		}
123		return nil
124	}
125	
126	// SafelyAdvanceLocalRef updates localRefName to include targetHash without
127	// dropping local-only commits. Missing and behind refs advance to targetHash;
128	// already-current or locally-ahead refs are left unchanged; diverged refs replay
129	// commits after the merge-base onto targetHash and move localRefName to the
130	// replayed tip. If there is no merge-base and the reachable histories are
131	// complete, the full local chain is replayed.
132	func SafelyAdvanceLocalRef(ctx context.Context, repo *git.Repository, localRefName plumbing.ReferenceName, targetHash plumbing.Hash) error {
133		currentLocal, localErr := repo.Reference(localRefName, true)
134		if localErr != nil {
135			if !errors.Is(localErr, plumbing.ErrReferenceNotFound) {
136				return fmt.Errorf("failed to read local ref %s: %w", localRefName, localErr)
137			}
138			return setRefHash(repo, localRefName, targetHash)
139		}
140	
141		localHash := currentLocal.Hash()
142		if localHash == targetHash {
143			return nil
144		}
145	
146		repoPath, err := getRepoPath(repo)
147		if err != nil {
148			return fmt.Errorf("failed to get repo path: %w", err)
149		}
150	
151		mergeBase, err := getMergeBase(ctx, repoPath, localHash.String(), targetHash.String())
152		if errors.Is(err, errNoMergeBase) {
153			shallow, shallowErr := hasReachableShallowBoundary(ctx, repo, repoPath, localHash.String(), targetHash.String())
154			if shallowErr != nil {
155				return fmt.Errorf("failed to check shallow history for %s: %w", localRefName, shallowErr)
156			}
157			if shallow {
158				return fmt.Errorf("no merge base for %s, and reachable shallow history prevents proving refs are disconnected; run 'entire doctor' or 'git fetch --unshallow' and try again", localRefName)
159			}
160			return replayDisconnectedLocalRef(ctx, repo, repoPath, localRefName, localHash, targetHash)
161		}
162		if err != nil {
163			return fmt.Errorf("failed to find merge base for %s: %w", localRefName, err)
164		}
165		if mergeBase == targetHash {
166			return nil
167		}
168		if mergeBase == localHash {
169			return setRefHash(repo, localRefName, targetHash)
170		}
171	
