719	// TestCollectCommitChain_DepthLimit verifies that collectCommitChain returns an error
720	// when the commit chain exceeds MaxCommitTraversalDepth without reaching a root commit.
721	func TestCollectCommitChain_DepthLimit(t *testing.T) {
722		t.Parallel()
723	
724		dir := t.TempDir()
725		testutil.InitRepo(t, dir)
726		repo, err := git.PlainOpen(dir)
727		require.NoError(t, err)
728	
729		// Create an empty tree for all commits.
730		emptyTree := &object.Tree{Entries: []object.TreeEntry{}}
731		treeObj := repo.Storer.NewEncodedObject()
732		require.NoError(t, emptyTree.Encode(treeObj))
733		treeHash, err := repo.Storer.SetEncodedObject(treeObj)
734		require.NoError(t, err)
735	
736		// Build a linear chain of MaxCommitTraversalDepth+1 commits (all have parents,
737		// so none is a root). collectCommitChain should bail out at the depth limit.
738		var tip plumbing.Hash
739		for i := range MaxCommitTraversalDepth + 1 {
740			c := &object.Commit{
741				TreeHash:  treeHash,
742				Author:    object.Signature{Name: "test", Email: "test@test.com", When: time.Now().Add(time.Duration(i) * time.Second)},
743				Committer: object.Signature{Name: "test", Email: "test@test.com", When: time.Now().Add(time.Duration(i) * time.Second)},
744				Message:   "commit\n",
745			}
746			if tip != plumbing.ZeroHash {
747				c.ParentHashes = []plumbing.Hash{tip}
748			}
749			obj := repo.Storer.NewEncodedObject()
750			require.NoError(t, c.Encode(obj))
751			h, sErr := repo.Storer.SetEncodedObject(obj)
752			require.NoError(t, sErr)
753			tip = h
754		}
755	
756		_, err = collectCommitChain(repo, tip, nil)
757		require.Error(t, err)
758		assert.Contains(t, err.Error(), "exceeded")
759		assert.Contains(t, err.Error(), "without reaching root")
760	}
