762	// TestCollectCommitChain_StopsAtShallowBoundary verifies that collectCommitChain
763	// treats commits listed in the shallow set as roots, stopping the walk at the
764	// boundary even when the boundary commit has a parent SHA recorded in the object
765	// store. Without this behaviour, a shallow checkpoint repo whose remote v1 was
766	// rebuilt elsewhere would produce a phantom chain of stale commits.
767	func TestCollectCommitChain_StopsAtShallowBoundary(t *testing.T) {
768		t.Parallel()
769	
770		dir := t.TempDir()
771		testutil.InitRepo(t, dir)
772		repo, err := git.PlainOpen(dir)
773		require.NoError(t, err)
774	
775		emptyTree := &object.Tree{Entries: []object.TreeEntry{}}
776		treeObj := repo.Storer.NewEncodedObject()
777		require.NoError(t, emptyTree.Encode(treeObj))
778		treeHash, err := repo.Storer.SetEncodedObject(treeObj)
779		require.NoError(t, err)
780	
781		// Build a linear chain of 10 commits. Without shallow, the walk should
782		// return all 10. With the 4th from the tip marked shallow, it should stop
783		// at that commit, returning 4 entries (tip + 3 below it, including the
784		// shallow boundary itself, treated as a root).
785		var tip plumbing.Hash
786		hashes := make([]plumbing.Hash, 0, 10)
787		for i := range 10 {
788			c := &object.Commit{
789				TreeHash:  treeHash,
790				Author:    object.Signature{Name: "test", Email: "test@test.com", When: time.Now().Add(time.Duration(i) * time.Second)},
791				Committer: object.Signature{Name: "test", Email: "test@test.com", When: time.Now().Add(time.Duration(i) * time.Second)},
792				Message:   "commit\n",
793			}
794			if tip != plumbing.ZeroHash {
795				c.ParentHashes = []plumbing.Hash{tip}
796			}
797			obj := repo.Storer.NewEncodedObject()
798			require.NoError(t, c.Encode(obj))
799			h, sErr := repo.Storer.SetEncodedObject(obj)
800			require.NoError(t, sErr)
801			hashes = append(hashes, h)
802			tip = h
803		}
804	
805		// Without shallow set: full chain of 10.
806		chain, err := collectCommitChain(repo, tip, nil)
807		require.NoError(t, err)
808		assert.Len(t, chain, 10, "without shallow, expect full chain")
809	
810		// With the 4th-from-tip (index 6 in build order) marked shallow: walk
811		// stops there. Result is oldest-first: shallow boundary, then up to tip
812		// = 4 commits.
813		shallow := map[plumbing.Hash]bool{hashes[6]: true}
814		chain, err = collectCommitChain(repo, tip, shallow)
815		require.NoError(t, err)
816		require.Len(t, chain, 4, "expect tip + 3 commits down to the shallow boundary inclusive")
817		assert.Equal(t, hashes[6], chain[0].Hash, "oldest entry should be the shallow boundary")
818		assert.Equal(t, tip, chain[3].Hash, "newest entry should be the tip")
819	}
