852	// TestMetadataDisconnected_ShallowSuppressesFalsePositive verifies that a
853	// merge-base miss on a SHALLOW repo is not reported as a disconnection. The
854	// common ancestor may live below the shallow boundary, where git has no
855	// objects, so `git merge-base` falsely reports "no common ancestor".
856	// Suppressing this prevents a doomed full-history reconcile on an ordinary
857	// diverged-but-behind metadata branch (the shallow-clone incident: local fell
858	// behind while out of office, the clone stayed shallow, and merge-base could
859	// not see the still-existing shared ancestor).
860	func TestMetadataDisconnected_ShallowSuppressesFalsePositive(t *testing.T) {
861		t.Parallel()
862	
863		dir := t.TempDir()
864		testutil.InitRepo(t, dir)
865		runGit := gitRunnerInDir(t, dir)
866	
867		// Shared ancestor B.
868		require.NoError(t, os.WriteFile(filepath.Join(dir, "f.txt"), []byte("base"), 0o644))
869		runGit("add", ".")
870		runGit("commit", "-m", "base")
871		base := runGit("rev-parse", "HEAD")
872	
873		// Remote tip C on top of B.
874		require.NoError(t, os.WriteFile(filepath.Join(dir, "f.txt"), []byte("remote"), 0o644))
875		runGit("add", ".")
876		runGit("commit", "-m", "remote")
877		remoteTip := runGit("rev-parse", "HEAD")
878	
879		// Local tip D, also on top of B (diverged-but-connected).
880		runGit("checkout", "-b", "local", base)
881		require.NoError(t, os.WriteFile(filepath.Join(dir, "g.txt"), []byte("local"), 0o644))
882		runGit("add", ".")
883		runGit("commit", "-m", "local")
884		localTip := runGit("rev-parse", "HEAD")
885	
886		ctx := context.Background()
887	
888		// Sanity: with full history they share ancestor B → connected.
889		repo, err := git.PlainOpen(dir)
890		require.NoError(t, err)
891		disconnected, err := metadataDisconnected(ctx, repo, dir, localTip, remoteTip)
892		require.NoError(t, err)
893		require.False(t, disconnected, "full-history repo shares ancestor B")
894	
895		// Make the repo shallow at both tips, cutting B out of view. The shared
896		// ancestor is now hidden and bare merge-base reports no common ancestor.
897		require.NoError(t, os.WriteFile(filepath.Join(dir, ".git", "shallow"),
898			[]byte(localTip+"\n"+remoteTip+"\n"), 0o644))
899	
900		// Precondition: the bare merge-base check now misses.
901		rawDisconnected, err := isDisconnected(ctx, dir, localTip, remoteTip)
902		require.NoError(t, err)
903		require.True(t, rawDisconnected,
904			"precondition: shallow boundary should hide the common ancestor from merge-base")
905	
906		// The shallow-aware check must suppress the false positive. Re-open so the
907		// storer picks up the freshly written shallow file.
908		shallowRepo, err := git.PlainOpen(dir)
909		require.NoError(t, err)
910		disconnected, err = metadataDisconnected(ctx, shallowRepo, dir, localTip, remoteTip)
911		require.NoError(t, err)
912		assert.False(t, disconnected,
913			"shallow metadata history: a merge-base miss must not be treated as a disconnection")
914	}
915	
916	// TestMetadataDisconnected_GenuineDisconnectionOnFullRepo verifies that on a
917	// non-shallow repo a real merge-base miss (two unrelated roots) is still
918	// reported as disconnected — the suppression only applies to shallow clones.
919	func TestMetadataDisconnected_GenuineDisconnectionOnFullRepo(t *testing.T) {
920		t.Parallel()
921	
922		dir := t.TempDir()
923		testutil.InitRepo(t, dir)
924		runGit := gitRunnerInDir(t, dir)
925	
926		require.NoError(t, os.WriteFile(filepath.Join(dir, "f.txt"), []byte("a"), 0o644))
927		runGit("add", ".")
928		runGit("commit", "-m", "a")
929		tipA := runGit("rev-parse", "HEAD")
930	
931		// Unrelated orphan root — no shared ancestry with tipA.
932		runGit("checkout", "--orphan", "orphan")
933		runGit("rm", "-rf", ".")
934		require.NoError(t, os.WriteFile(filepath.Join(dir, "h.txt"), []byte("b"), 0o644))
935		runGit("add", ".")
936		runGit("commit", "-m", "b")
937		tipB := runGit("rev-parse", "HEAD")
938	
939		ctx := context.Background()
940		repo, err := git.PlainOpen(dir)
941		require.NoError(t, err)
942		disconnected, err := metadataDisconnected(ctx, repo, dir, tipA, tipB)
943		require.NoError(t, err)
944		assert.True(t, disconnected,
945			"non-shallow repo with unrelated roots must be reported as disconnected")
946	}
947	
948	// TestReconcileDisconnected_AllEmptyOrphans verifies that when all local commits
949	// are empty-tree orphan commits (the exact bug artifact), reconciliation resets
950	// the local branch to the remote tip without cherry-picking.
951	func TestReconcileDisconnected_AllEmptyOrphans(t *testing.T) {
952		t.Parallel()
953	
954		bareDir := initBareWithMetadataBranch(t)
955		cloneDir, run := cloneWithConfig(t, bareDir)
956	
957		// Create a disconnected local branch with ONLY empty-tree commits
958		// (simulating the empty-orphan bug in a repo that never had real checkpoints)
959		run("checkout", "--orphan", "temp-orphan")
960		run("rm", "-rf", ".")
961		// Commit with empty tree (git allows this with --allow-empty)
962		run("commit", "--allow-empty", "-m", "empty orphan init")
963		run("branch", "-f", paths.MetadataBranchName, "temp-orphan")
964		run("checkout", "main")
965	
966		repo, err := git.PlainOpen(cloneDir)
967		require.NoError(t, err)
968	
969		// Get remote hash before reconciliation
970		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
971		remoteRef, err := repo.Reference(remoteRefName, true)
972		require.NoError(t, err)
973	
974		err = ReconcileDisconnectedMetadataRef(context.Background(), repo, metadataLocalRef(), metadataOriginRemoteRef(), io.Discard)
975		require.NoError(t, err)
976	
977		// Local branch should now point to the remote tip (reset, not cherry-picked)
978		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
979		localRef, err := repo.Reference(refName, true)
980		require.NoError(t, err)
981	
982		assert.Equal(t, remoteRef.Hash(), localRef.Hash(),
983			"local should be reset to remote tip when all local commits are empty orphans")
984	}
985	
986	// TestReconcileDisconnected_CherryPickDeletion verifies that when a local commit
987	// deletes a file from its parent, the deletion is correctly propagated during
988	// cherry-pick reconciliation.
989	func TestReconcileDisconnected_CherryPickDeletion(t *testing.T) {
990		t.Parallel()
991	
992		bareDir := initBareWithMetadataBranch(t)
993		cloneDir, run := cloneWithConfig(t, bareDir)
994	
995		// Create a disconnected local branch with two commits:
996		// 1. Adds two files
997		// 2. Deletes one of them
998		run("checkout", "--orphan", "temp-orphan")
999		run("rm", "-rf", ".")
1000	
1001		// Commit 1: add two checkpoint files
1002		dir1 := filepath.Join(cloneDir, "ab", "cdef012345")
1003		require.NoError(t, os.MkdirAll(dir1, 0o755))
1004		require.NoError(t, os.WriteFile(filepath.Join(dir1, "metadata.json"), []byte(`{"checkpoint_id":"abcdef012345"}`), 0o644))
1005	
1006		dir2 := filepath.Join(cloneDir, "cd", "ef01234567")
1007		require.NoError(t, os.MkdirAll(dir2, 0o755))
1008		require.NoError(t, os.WriteFile(filepath.Join(dir2, "metadata.json"), []byte(`{"checkpoint_id":"cdef01234567"}`), 0o644))
1009	
1010		run("add", ".")
1011		run("commit", "-m", "Checkpoint: add two")
1012	
1013		// Commit 2: delete the second checkpoint
1014		require.NoError(t, os.RemoveAll(filepath.Join(cloneDir, "cd")))
1015		run("add", "-A")
1016		run("commit", "-m", "Checkpoint: remove second")
1017	
1018		run("branch", "-f", paths.MetadataBranchName, "temp-orphan")
1019		run("checkout", "main")
1020	
1021		repo, err := git.PlainOpen(cloneDir)
1022		require.NoError(t, err)
1023	
1024		err = ReconcileDisconnectedMetadataRef(context.Background(), repo, metadataLocalRef(), metadataOriginRemoteRef(), io.Discard)
1025		require.NoError(t, err)
1026	
1027		// Verify merged tree: should have remote data + first local checkpoint,
1028		// but NOT the deleted second checkpoint
1029		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
1030		newRef, err := repo.Reference(refName, true)
1031		require.NoError(t, err)
1032		tipCommit, err := repo.CommitObject(newRef.Hash())
1033		require.NoError(t, err)
1034		tree, err := tipCommit.Tree()
1035		require.NoError(t, err)
1036	
1037		entries := make(map[string]object.TreeEntry)
1038		require.NoError(t, checkpoint.FlattenTree(repo, tree, "", entries))
1039	
1040		// Remote data should be present
1041		assert.Contains(t, entries, "metadata.json", "remote data should be preserved")
1042		// First local checkpoint should be present
1043		assert.Contains(t, entries, "ab/cdef012345/metadata.json", "kept checkpoint should be present")
1044		// Second local checkpoint should be deleted
1045		assert.NotContains(t, entries, "cd/ef01234567/metadata.json", "deleted checkpoint should not be present")
1046	}
