// TestMetadataDisconnected_ShallowRemoteTipDeepLocal reproduces the actual
// shallow-clone incident faithfully: the LOCAL metadata branch is a complete
// chain reaching its own root, and ONLY the freshly-fetched remote tip carries
// the shallow boundary (the --depth=1 FetchMetadataTreeOnly cut its parent).
//
// This is stricter than TestMetadataDisconnected_ShallowSuppressesFalsePositive,
// which marks BOTH tips shallow — there the local hash alone reaches a boundary,
// so the suppression would fire even if it only inspected the local commit. In
// production the local history is complete and never touches .git/shallow; only
// the remote tip does. So the suppression MUST inspect the remote hash too. A
// regression that checked only the local hash would let the false-positive
// disconnection through here and re-trigger the doomed reconcile.
func TestMetadataDisconnected_ShallowRemoteTipDeepLocal(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	runGit := gitRunnerInDir(t, dir)

	// Shared ancestor B.
	require.NoError(t, os.WriteFile(filepath.Join(dir, "f.txt"), []byte("base"), 0o644))
	runGit("add", ".")
	runGit("commit", "-m", "base")
	base := runGit("rev-parse", "HEAD")

	// Remote tip C on top of B.
	require.NoError(t, os.WriteFile(filepath.Join(dir, "f.txt"), []byte("remote"), 0o644))
	runGit("add", ".")
	runGit("commit", "-m", "remote")
	remoteTip := runGit("rev-parse", "HEAD")

	// Local branch: a complete chain on top of B that reaches the root. It
	// shares ancestor B with the remote but never touches the shallow boundary.
	runGit("checkout", "-b", "local", base)
	for _, n := range []string{"l1", "l2", "l3"} {
		require.NoError(t, os.WriteFile(filepath.Join(dir, n+".txt"), []byte(n), 0o644))
		runGit("add", ".")
		runGit("commit", "-m", n)
	}
	localTip := runGit("rev-parse", "HEAD")

	ctx := context.Background()

	// Sanity: full history shares ancestor B → connected.
	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)
	disconnected, err := metadataDisconnected(ctx, repo, dir, localTip, remoteTip)
	require.NoError(t, err)
	require.False(t, disconnected, "full-history repo shares ancestor B")

	// Mark ONLY the remote tip shallow, severing C->B. The local chain stays
	// complete and reaches its root without crossing the boundary.
	require.NoError(t, os.WriteFile(filepath.Join(dir, ".git", "shallow"),
		[]byte(remoteTip+"\n"), 0o644))

	// Precondition: bare merge-base now misses (C's parent is gone)...
	rawDisconnected, err := isDisconnected(ctx, dir, localTip, remoteTip)
	require.NoError(t, err)
	require.True(t, rawDisconnected,
		"precondition: shallow remote tip should hide the common ancestor from merge-base")

	// ...and the local chain alone never reaches a shallow boundary, so only the
	// remote-hash check can suppress the false positive.
	shallowRepo, err := git.PlainOpen(dir)
	require.NoError(t, err)
	localReaches, err := hasReachableShallowBoundary(ctx, shallowRepo, dir, localTip)
	require.NoError(t, err)
	require.False(t, localReaches,
		"precondition: the complete local chain must not reach the shallow boundary on its own")

	disconnected, err = metadataDisconnected(ctx, shallowRepo, dir, localTip, remoteTip)
	require.NoError(t, err)
	assert.False(t, disconnected,
		"shallow remote tip: a merge-base miss must not be treated as a disconnection even when the local chain is complete")
}

// TestReconcileDisconnected_ShallowCloneNoOps reproduces the reported push
// symptom end-to-end: on a shallow checkpoint clone where `git merge-base`
// falsely misses, ReconcileDisconnectedMetadataRef must no-op instead of
// entering the cherry-pick path and aborting with "commit chain exceeded 1000
// commits without reaching root". It exercises the real ref names the push hook
// passes (local entire/checkpoints/v1 + origin remote-tracking ref).
func TestReconcileDisconnected_ShallowCloneNoOps(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	runGit := gitRunnerInDir(t, dir)

	// Shared ancestor B on the metadata branch.
	require.NoError(t, os.WriteFile(filepath.Join(dir, "metadata.json"), []byte(`{"v":0}`), 0o644))
	runGit("add", ".")
	runGit("commit", "-m", "base")
	base := runGit("rev-parse", "HEAD")

	// Remote tip C on top of B — becomes the shallow-bounded origin ref.
	require.NoError(t, os.WriteFile(filepath.Join(dir, "metadata.json"), []byte(`{"v":1}`), 0o644))
	runGit("add", ".")
	runGit("commit", "-m", "remote checkpoint")
	remoteTip := runGit("rev-parse", "HEAD")

	// Local metadata branch: a complete chain on top of B (diverged-but-behind),
	// reaching root without touching the shallow boundary.
	runGit("checkout", "-b", paths.MetadataBranchName, base)
	for _, n := range []string{"a", "b", "c"} {
		require.NoError(t, os.MkdirAll(filepath.Join(dir, n, "0"), 0o755))
		require.NoError(t, os.WriteFile(filepath.Join(dir, n, "0", "metadata.json"), []byte(`{"id":"`+n+`"}`), 0o644))
		runGit("add", ".")
		runGit("commit", "-m", "Checkpoint: "+n)
	}
	localTip := runGit("rev-parse", "HEAD")

	// Publish the remote tip as the origin remote-tracking ref the push hook reads.
	runGit("update-ref", metadataOriginRemoteRef().String(), remoteTip)

	// Mark ONLY the remote tip shallow, severing C->B so merge-base misses.
	require.NoError(t, os.WriteFile(filepath.Join(dir, ".git", "shallow"),
		[]byte(remoteTip+"\n"), 0o644))

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	// Precondition: without the shallow-aware suppression this setup is exactly
	// what triggered the doomed reconcile (merge-base miss on a shallow clone).
	rawDisconnected, err := isDisconnected(context.Background(), dir, localTip, remoteTip)
	require.NoError(t, err)
	require.True(t, rawDisconnected, "precondition: shallow clone makes merge-base miss")

	require.NoError(t, ReconcileDisconnectedMetadataRef(
		context.Background(), repo, metadataLocalRef(), metadataOriginRemoteRef(), io.Discard),
		"reconcile must no-op on a shallow clone, not abort with the 1000-commit error")

	// Local ref must be left untouched — no cherry-pick, no reset.
	localRef, err := repo.Reference(metadataLocalRef(), true)
	require.NoError(t, err)
	assert.Equal(t, localTip, localRef.Hash().String(),
		"local metadata ref must be unchanged when the disconnection is a shallow false positive")
}

