// buildEmptyTreeCommit writes a commit with an empty tree and the given parents,
// returning its hash. Times are offset by seq so each commit hashes uniquely.
func buildEmptyTreeCommit(t *testing.T, repo *git.Repository, treeHash plumbing.Hash, parents []plumbing.Hash, msg string, seq int) plumbing.Hash {
	t.Helper()
	when := time.Unix(1700000000, 0).Add(time.Duration(seq) * time.Second)
	c := &object.Commit{
		TreeHash:     treeHash,
		ParentHashes: parents,
		Author:       object.Signature{Name: "test", Email: "test@test.com", When: when},
		Committer:    object.Signature{Name: "test", Email: "test@test.com", When: when},
		Message:      msg + "\n",
	}
	obj := repo.Storer.NewEncodedObject()
	require.NoError(t, c.Encode(obj))
	h, err := repo.Storer.SetEncodedObject(obj)
	require.NoError(t, err)
	return h
}

// TestReconcileDisconnected_ShallowClone1000CommitSymptom reproduces the exact
// production failure reported on `git push` against a shallow checkpoint clone:
//
//	[entire] Detected disconnected session metadata (local and remote share no common ancestor)
//	[entire] Warning: couldn't sync entire/checkpoints/v1: metadata reconciliation
//	  failed: failed to collect local commits: commit chain exceeded 1000 commits
//	  without reaching root; aborting reconciliation
//
// Sequence of events being modelled:
//   - resume/explain fetch the metadata tip with --depth=1, so the remote tip
//     carries a shallow boundary (its parent is absent from the object store).
//   - The local metadata branch is a deep, diverged-but-behind chain that shares
//     an ancestor (B) with the remote — but B lives below the remote's shallow
//     boundary, so `git merge-base` reports "no common ancestor".
//   - The buggy code trusts that miss, declares the branch disconnected, and
//     walks the full local history to cherry-pick it. The chain is longer than
//     MaxCommitTraversalDepth, so collectCommitChain aborts with the 1000-commit
//     error and the whole push sync fails.
//
// The shallow-aware suppression (metadataDisconnected) must recognise that the
// merge-base miss is an artifact of the shallow boundary and no-op instead. With
// the fix reverted, this test fails with the exact "commit chain exceeded 1000
// commits without reaching root" error, reproducing the symptom.
func TestReconcileDisconnected_ShallowClone1000CommitSymptom(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	runGit := gitRunnerInDir(t, dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	// Empty tree shared by every synthetic commit — collectCommitChain aborts on
