	repo := mergeTestRepo(t)

	remoteTip := commitTree(t, repo,
		buildTree(t, repo, map[string]string{"aa/aaaaaaaaaa/metadata.json": `{"id":"a"}`}), nil, 1)
	localTip := commitTree(t, repo,
		buildTree(t, repo, map[string]string{"cc/cccccccccc/metadata.json": `{"id":"c"}`}), nil, 2)

	newTip, err := MergeMetadataTip(context.Background(), repo, localTip, remoteTip, io.Discard)
	require.NoError(t, err)

	// Single linear commit on top of the remote tip — push fast-forwards.
	newCommit, err := repo.CommitObject(newTip)
	require.NoError(t, err)
	require.Equal(t, []plumbing.Hash{remoteTip}, newCommit.ParentHashes,
		"merged tip must be a single commit parented on the remote tip")

	files := treeFiles(t, repo, newCommit.TreeHash)
	assert.Contains(t, files, "aa/aaaaaaaaaa/metadata.json", "remote checkpoint preserved")
	assert.Contains(t, files, "cc/cccccccccc/metadata.json", "local checkpoint preserved")
}

// TestMergeMetadataTip_DeepLocalChainDoesNotWalk builds a local chain deeper
// than MaxCommitTraversalDepth, disconnected from the remote tip — the exact
// shape that made the old cherry-pick reconcile abort with "commit chain
// exceeded 1000 commits". MergeMetadataTip reads only the tip trees, so it
// completes regardless of depth.
func TestMergeMetadataTip_DeepLocalChainDoesNotWalk(t *testing.T) {
	t.Parallel()
	repo := mergeTestRepo(t)

	remoteTip := commitTree(t, repo,
		buildTree(t, repo, map[string]string{"aa/aaaaaaaaaa/metadata.json": `{"id":"a"}`}), nil, 1)

	localTree := buildTree(t, repo, map[string]string{"cc/cccccccccc/metadata.json": `{"id":"c"}`})
	var localTip plumbing.Hash
	for i := range MaxCommitTraversalDepth + 2 {
		var parents []plumbing.Hash
		if localTip != plumbing.ZeroHash {
			parents = []plumbing.Hash{localTip}
		}
		localTip = commitTree(t, repo, localTree, parents, i+2)
	}

	newTip, err := MergeMetadataTip(context.Background(), repo, localTip, remoteTip, io.Discard)
	require.NoError(t, err, "deep local chain must not trigger a history walk")

	newCommit, err := repo.CommitObject(newTip)
	require.NoError(t, err)
	files := treeFiles(t, repo, newCommit.TreeHash)
	assert.Contains(t, files, "aa/aaaaaaaaaa/metadata.json")
	assert.Contains(t, files, "cc/cccccccccc/metadata.json")
}

// TestMergeMetadataTip_FastForwardWhenLocalAddsNothing: when the local tip
// contributes no shard the remote lacks, the result is the remote tip itself —
// no redundant empty merge commit.
func TestMergeMetadataTip_FastForwardWhenLocalAddsNothing(t *testing.T) {
	t.Parallel()
	repo := mergeTestRepo(t)

	remoteTip := commitTree(t, repo, buildTree(t, repo, map[string]string{
		"aa/aaaaaaaaaa/metadata.json": `{"id":"a"}`,
