package strategy

import (
	"context"
	"io"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/testutil"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/filemode"
	"github.com/go-git/go-git/v6/plumbing/object"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// commitTree writes a commit holding treeHash with the given parents and
// returns its hash. seq offsets the timestamp so commits hash uniquely.
func commitTree(t *testing.T, repo *git.Repository, treeHash plumbing.Hash, parents []plumbing.Hash, seq int) plumbing.Hash {
	t.Helper()
	when := time.Unix(1700000000, 0).Add(time.Duration(seq) * time.Second)
	c := &object.Commit{
		TreeHash:     treeHash,
		ParentHashes: parents,
		Author:       object.Signature{Name: "test", Email: "test@test.com", When: when},
		Committer:    object.Signature{Name: "test", Email: "test@test.com", When: when},
		Message:      "checkpoint\n",
	}
	obj := repo.Storer.NewEncodedObject()
	require.NoError(t, c.Encode(obj))
	h, err := repo.Storer.SetEncodedObject(obj)
	require.NoError(t, err)
	return h
}

// mergeTestRepo returns an opened repo backed by an isolated temp dir. Only its
// object store is used — these tests build trees directly via plumbing.
func mergeTestRepo(t *testing.T) *git.Repository {
	t.Helper()
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)
	return repo
}

func writeBlob(t *testing.T, repo *git.Repository, content string) plumbing.Hash {
	t.Helper()
	obj := repo.Storer.NewEncodedObject()
	obj.SetType(plumbing.BlobObject)
	w, err := obj.Writer()
	require.NoError(t, err)
	_, err = w.Write([]byte(content))
	require.NoError(t, err)
	require.NoError(t, w.Close())
	h, err := repo.Storer.SetEncodedObject(obj)
	require.NoError(t, err)
	return h
}

// buildTree assembles a tree from a path->content map and returns its hash.
func buildTree(t *testing.T, repo *git.Repository, files map[string]string) plumbing.Hash {
	t.Helper()
	var changes []checkpoint.TreeChange
	for path, content := range files {
		entry := object.TreeEntry{Mode: filemode.Regular, Hash: writeBlob(t, repo, content)}
		changes = append(changes, checkpoint.TreeChange{Path: path, Entry: &entry})
	}
	h, err := checkpoint.ApplyTreeChanges(context.Background(), repo, plumbing.ZeroHash, changes)
	require.NoError(t, err)
	return h
}

// treeFiles flattens a tree back to a path->content map for assertions.
func treeFiles(t *testing.T, repo *git.Repository, treeHash plumbing.Hash) map[string]string {
	t.Helper()
	tree, err := repo.TreeObject(treeHash)
	require.NoError(t, err)
	entries := map[string]object.TreeEntry{}
	require.NoError(t, checkpoint.FlattenTree(repo, tree, "", entries))
	out := make(map[string]string, len(entries))
	for path, entry := range entries {
		blob, err := repo.BlobObject(entry.Hash)
		require.NoError(t, err)
		rd, err := blob.Reader()
		require.NoError(t, err)
		content, err := io.ReadAll(rd)
		require.NoError(t, rd.Close())
		require.NoError(t, err)
		out[path] = string(content)
	}
	return out
}

// TestMergeTipTrees_AdditiveUnion is the common case: distinct checkpoints on
// each side, unique shard paths, so the merge is a clean union with no conflicts.
func TestMergeTipTrees_AdditiveUnion(t *testing.T) {
	t.Parallel()
	repo := mergeTestRepo(t)

	remote := buildTree(t, repo, map[string]string{
		"ab/cdef012345/metadata.json": `{"id":"abcdef012345"}`,
	})
	local := buildTree(t, repo, map[string]string{
		"ab/cdef012345/metadata.json": `{"id":"abcdef012345"}`, // identical, shared
		"cd/ef01234567/metadata.json": `{"id":"cdef01234567"}`, // local-only
	})

	res, err := mergeTipTrees(context.Background(), repo, remote, local)
	require.NoError(t, err)

	files := treeFiles(t, repo, res.TreeHash)
	assert.Contains(t, files, "ab/cdef012345/metadata.json", "remote shard preserved")
	assert.Contains(t, files, "cd/ef01234567/metadata.json", "local-only shard added")
	assert.Equal(t, []string{"cd/ef01234567/metadata.json"}, res.AddedFromLocal)
	assert.Empty(t, res.Conflicts, "unique shard paths never conflict")
}

// TestMergeTipTrees_NoSharedAncestryStillUnions is the headline win: the two
// tips come from disconnected histories (the exact situation that defeats
// merge-base and triggers the 1000-commit walk). The tip-tree union doesn't
// read history at all, so it merges both sides' checkpoints regardless.
func TestMergeTipTrees_NoSharedAncestryStillUnions(t *testing.T) {
	t.Parallel()
	repo := mergeTestRepo(t)

	// Remote line and local line share nothing in common.
	remote := buildTree(t, repo, map[string]string{
		"11/1111111111/metadata.json": `{"id":"111111111111"}`,
		"22/2222222222/metadata.json": `{"id":"222222222222"}`,
	})
	local := buildTree(t, repo, map[string]string{
		"33/3333333333/metadata.json": `{"id":"333333333333"}`,
		"44/4444444444/metadata.json": `{"id":"444444444444"}`,
	})

	res, err := mergeTipTrees(context.Background(), repo, remote, local)
	require.NoError(t, err)

	files := treeFiles(t, repo, res.TreeHash)
	for _, p := range []string{
		"11/1111111111/metadata.json", "22/2222222222/metadata.json",
		"33/3333333333/metadata.json", "44/4444444444/metadata.json",
	} {
		assert.Contains(t, files, p, "all checkpoints from both disconnected tips preserved")
	}
	assert.Len(t, res.AddedFromLocal, 2)
	assert.Empty(t, res.Conflicts)
}

// TestMergeTipTrees_DeleteResurrection documents the deliberate downside: a
// shard the remote DELETED (e.g. cleanup removed an orphaned checkpoint) but
// that local still carries is indistinguishable from a local addition without a
// merge-base, so the union RESURRECTS it. This test pins that behaviour so the
// deletion policy (accept vs. tombstone) is a conscious choice.
func TestMergeTipTrees_DeleteResurrection(t *testing.T) {
	t.Parallel()
	repo := mergeTestRepo(t)

	// Remote has dropped "ab/..." (only "cd/..." remains); local still has both.
	remote := buildTree(t, repo, map[string]string{
		"cd/ef01234567/metadata.json": `{"id":"cdef01234567"}`,
	})
	local := buildTree(t, repo, map[string]string{
		"ab/cdef012345/metadata.json": `{"id":"abcdef012345"}`, // remote-deleted
		"cd/ef01234567/metadata.json": `{"id":"cdef01234567"}`,
	})

	res, err := mergeTipTrees(context.Background(), repo, remote, local)
	require.NoError(t, err)

	files := treeFiles(t, repo, res.TreeHash)
	assert.Contains(t, files, "ab/cdef012345/metadata.json",
		"KNOWN TRADE-OFF: remote-deleted shard is resurrected by a base-less union")
	assert.Equal(t, []string{"ab/cdef012345/metadata.json"}, res.AddedFromLocal,
		"the resurrected shard is reported as a local addition")
}

// TestMergeTipTrees_SameCheckpointConflict covers two machines condensing the
// SAME checkpoint id. Sessions are themselves sharded (<id>/<n>/...), so the
// per-session files union cleanly; only the per-checkpoint summary metadata.json
// is a true same-path conflict. The prototype resolves it local-wins and
// reports the path so a caller could instead merge it semantically.
func TestMergeTipTrees_SameCheckpointConflict(t *testing.T) {
	t.Parallel()
	repo := mergeTestRepo(t)

	remote := buildTree(t, repo, map[string]string{
		"aa/aaaaaaaaaa/metadata.json":   `{"id":"aaaaaaaaaaaa","session_count":1}`,
		"aa/aaaaaaaaaa/0/metadata.json": `{"session_id":"remote-session"}`,
	})
	local := buildTree(t, repo, map[string]string{
		"aa/aaaaaaaaaa/metadata.json":   `{"id":"aaaaaaaaaaaa","session_count":1,"local":true}`,
		"aa/aaaaaaaaaa/1/metadata.json": `{"session_id":"local-session"}`,
	})

	res, err := mergeTipTrees(context.Background(), repo, remote, local)
	require.NoError(t, err)

	files := treeFiles(t, repo, res.TreeHash)
	// Per-session shards from both sides survive (additive within the checkpoint).
	assert.Contains(t, files, "aa/aaaaaaaaaa/0/metadata.json", "remote session preserved")
	assert.Contains(t, files, "aa/aaaaaaaaaa/1/metadata.json", "local session added")
	// The summary file is the only real conflict; local content wins.
	assert.JSONEq(t, `{"id":"aaaaaaaaaaaa","session_count":1,"local":true}`,
		files["aa/aaaaaaaaaa/metadata.json"], "summary conflict resolved local-wins")
	assert.Equal(t, []string{"aa/aaaaaaaaaa/metadata.json"}, res.Conflicts,
		"only the summary file is reported as a conflict")
	assert.Equal(t, []string{"aa/aaaaaaaaaa/1/metadata.json"}, res.AddedFromLocal)
}

