package strategy

import (
	"context"
	"fmt"
	"io"
	"sort"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// MergeTipResult reports the outcome of a tip-tree union performed by
// mergeTipTrees.
type MergeTipResult struct {
	// TreeHash is the merged tree — the union of the remote and local tip trees.
	TreeHash plumbing.Hash
	// AddedFromLocal lists paths present only in the local tip, layered onto the
	// remote tip (new local-only checkpoint shards).
	AddedFromLocal []string
	// Conflicts lists paths present in BOTH tips with differing content — the
	// same shard touched on both sides. mergeTipTrees resolves these by taking
	// the LOCAL content; the list is surfaced so callers can log or escalate to
	// a semantic merge (e.g. recomputing a checkpoint's session summary).
	Conflicts []string
}

// mergeTipTrees unions the local and remote checkpoint tip trees by path,
// producing a single merged tree. It reads only the two tip trees and never
// walks commit ancestry, so — unlike the cherry-pick reconcile — it is immune
// to shallow boundaries, missing merge-bases, and deep histories. The metadata
// branch is effectively a set of content-addressed shards keyed by path
// (<id[:2]>/<id[2:]>/...), and merging two states is a set union of that set.
//
// Resolution, per path:
//   - present only in remote     -> kept (it is already in the base tree)
//   - present only in local      -> added            (recorded in AddedFromLocal)
//   - present in both, same hash -> kept (no-op)
//   - present in both, differ    -> local content wins (recorded in Conflicts)
//
// IMPORTANT — deletion semantics: with only two tips and no merge-base, this
// cannot distinguish "local ADDED a shard" from "remote DELETED a shard". A
// path the remote intentionally removed (e.g. via cleanup) but that local still
// carries reappears as local-only and is therefore RESURRECTED. That is the
// deliberate trade-off of dropping ancestry; if it matters, the deletion must
// be represented explicitly (a tombstone) rather than inferred from absence.
func mergeTipTrees(ctx context.Context, repo *git.Repository, remoteTreeHash, localTreeHash plumbing.Hash) (MergeTipResult, error) {
	remoteEntries, err := flattenTreeHash(repo, remoteTreeHash)
	if err != nil {
		return MergeTipResult{}, fmt.Errorf("flatten remote tip: %w", err)
	}
	localEntries, err := flattenTreeHash(repo, localTreeHash)
	if err != nil {
		return MergeTipResult{}, fmt.Errorf("flatten local tip: %w", err)
	}

	var (
		changes   []checkpoint.TreeChange
		added     []string
		conflicts []string
	)
	for path, localEntry := range localEntries {
		remoteEntry, inRemote := remoteEntries[path]
		switch {
		case !inRemote:
			added = append(added, path)
		case remoteEntry.Hash == localEntry.Hash:
			continue // identical shard — nothing to apply
		default:
			conflicts = append(conflicts, path)
		}
		entry := localEntry // local content wins on conflict; copy for &address
		changes = append(changes, checkpoint.TreeChange{Path: path, Entry: &entry})
	}

	// Deterministic output regardless of map iteration order.
	sort.Strings(added)
	sort.Strings(conflicts)

	mergedTree, err := checkpoint.ApplyTreeChanges(ctx, repo, remoteTreeHash, changes)
	if err != nil {
		return MergeTipResult{}, fmt.Errorf("apply local shards onto remote tip: %w", err)
	}

	return MergeTipResult{
		TreeHash:       mergedTree,
		AddedFromLocal: added,
		Conflicts:      conflicts,
	}, nil
}

// MergeMetadataTip unions the local metadata tip tree onto the remote tip and
// returns the hash the local ref should advance to. It is the ancestry-free
// replacement for the disconnected-metadata reconcile: it reads only the two
// tip trees (no merge-base, no commit-chain walk), so it cannot blow the
// traversal cap on a deep branch or be fooled by a shallow boundary.
//
// The result is a single commit parented on the remote tip (keeping the branch
// linear), with the union tree. When the local tip adds nothing the remote
// doesn't already have, it fast-forwards to the remote tip instead of creating
// an empty commit. Conflicting shards (same path, differing content) keep the
// local copy — see mergeTipTrees.
func MergeMetadataTip(ctx context.Context, repo *git.Repository, localTip, remoteTip plumbing.Hash, w io.Writer) (plumbing.Hash, error) {
	if remoteTip == plumbing.ZeroHash {
		return localTip, nil // nothing to merge onto
	}
	if localTip == plumbing.ZeroHash || localTip == remoteTip {
		return remoteTip, nil
	}

	remoteTree, err := commitTreeHash(repo, remoteTip)
	if err != nil {
		return plumbing.ZeroHash, err
	}
	localTree, err := commitTreeHash(repo, localTip)
	if err != nil {
		return plumbing.ZeroHash, err
	}

	res, err := mergeTipTrees(ctx, repo, remoteTree, localTree)
	if err != nil {
		return plumbing.ZeroHash, err
	}

	// Local contributes nothing the remote lacks — fast-forward to remote.
	if res.TreeHash == remoteTree {
		return remoteTip, nil
	}

	fmt.Fprintf(w, "[entire] Merging %d local checkpoint shard(s) onto remote tip...\n", len(res.AddedFromLocal))
	if len(res.Conflicts) > 0 {
		fmt.Fprintf(w, "[entire] %d shard(s) differed on both sides; kept the local copy\n", len(res.Conflicts))
	}

	return commitMergedTree(ctx, repo, res.TreeHash, remoteTip)
}

// commitTreeHash returns the tree hash of the commit at h.
func commitTreeHash(repo *git.Repository, h plumbing.Hash) (plumbing.Hash, error) {
	commit, err := repo.CommitObject(h)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("read commit %s: %w", h, err)
	}
	return commit.TreeHash, nil
}

// commitMergedTree writes a single commit holding treeHash, parented on parent,
// authored/committed by the repo identity, and returns its hash.
func commitMergedTree(ctx context.Context, repo *git.Repository, treeHash, parent plumbing.Hash) (plumbing.Hash, error) {
	name, email := GetGitAuthorFromRepo(repo)
	sig := object.Signature{Name: name, Email: email, When: time.Now()}
	commit := &object.Commit{
		TreeHash:     treeHash,
		ParentHashes: []plumbing.Hash{parent},
		Author:       sig,
		Committer:    sig,
		Message:      "Merge local checkpoints into remote tip\n",
	}
	checkpoint.SignCommitBestEffort(ctx, commit)

	obj := repo.Storer.NewEncodedObject()
	if err := commit.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("encode merge commit: %w", err)
	}
	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("store merge commit: %w", err)
	}
	return hash, nil
}

// flattenTreeHash resolves treeHash and returns its files keyed by full path.
// A zero hash yields an empty map (an absent tip contributes nothing).
func flattenTreeHash(repo *git.Repository, treeHash plumbing.Hash) (map[string]object.TreeEntry, error) {
	entries := map[string]object.TreeEntry{}
	if treeHash == plumbing.ZeroHash {
		return entries, nil
	}
	tree, err := repo.TreeObject(treeHash)
	if err != nil {
		return nil, fmt.Errorf("read tree %s: %w", treeHash, err)
	}
	if err := checkpoint.FlattenTree(repo, tree, "", entries); err != nil {
		return nil, fmt.Errorf("flatten tree %s: %w", treeHash, err)
	}
	return entries, nil
}

