// MergeMetadataTip layers the local tip's checkpoints onto the remote tip and
// returns the hash the local ref should advance to. It is the ancestry-free
// replacement for the disconnected-metadata reconcile: it reads only the two
// tip trees (no merge-base, no commit-chain walk), so it cannot blow the
// traversal cap on a deep branch or be fooled by a shallow boundary.
//
// The local-only shards (paths absent from the remote tip, or present with
// differing content — local wins) are grouped by checkpoint id and replayed as
// one "Checkpoint: <id>" commit each, chained onto the remote tip. This keeps
// the branch linear AND preserves the per-checkpoint commit subjects that
// downstream code relies on (e.g. author attribution via the commit log),
// without reading any commit ancestry. Empty-tree "Initialize metadata branch"
// orphans contribute no shards and so are naturally dropped.
//
// When the local tip adds nothing the remote lacks, it fast-forwards to the
// remote tip without creating a commit.
func MergeMetadataTip(ctx context.Context, repo *git.Repository, localTip, remoteTip plumbing.Hash, w io.Writer) (plumbing.Hash, error) {
	if remoteTip == plumbing.ZeroHash {
		return localTip, nil // nothing to merge onto
	}
	if localTip == plumbing.ZeroHash || localTip == remoteTip {
		return remoteTip, nil
	}

	remoteTree, err := commitTreeHash(repo, remoteTip)
	if err != nil {
		return plumbing.ZeroHash, err
	}
	localTree, err := commitTreeHash(repo, localTip)
	if err != nil {
		return plumbing.ZeroHash, err
	}

	remoteEntries, err := flattenTreeHash(repo, remoteTree)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("flatten remote tip: %w", err)
	}
	localEntries, err := flattenTreeHash(repo, localTree)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("flatten local tip: %w", err)
	}

	commits := planCheckpointCommits(localEntries, remoteEntries)
	if len(commits) == 0 {
		// Local contributes nothing the remote lacks — fast-forward to remote.
		return remoteTip, nil
	}

	fmt.Fprintf(w, "[entire] Merging %d local checkpoint(s) onto remote tip...\n", len(commits))

	currentTip, currentTree := remoteTip, remoteTree
	for _, c := range commits {
		changes := make([]checkpoint.TreeChange, 0, len(c.paths))
		for _, p := range c.paths {
			entry := localEntries[p]
			changes = append(changes, checkpoint.TreeChange{Path: p, Entry: &entry})
		}
		newTree, applyErr := checkpoint.ApplyTreeChanges(ctx, repo, currentTree, changes)
		if applyErr != nil {
			return plumbing.ZeroHash, fmt.Errorf("apply %s: %w", c.message, applyErr)
		}
		newTip, commitErr := commitMergedTree(ctx, repo, newTree, currentTip, c.message)
		if commitErr != nil {
			return plumbing.ZeroHash, commitErr
		}
		currentTip, currentTree = newTip, newTree
	}
	return currentTip, nil
}

// checkpointCommitPlan is one commit to replay onto the remote tip: the paths
// whose local entries to apply and the commit subject to use.
type checkpointCommitPlan struct {
	message string
	paths   []string
}

// planCheckpointCommits diffs the local tip against the remote tip and groups
// the local-only/differing paths into per-checkpoint commits. Paths are grouped
// by the checkpoint id parsed from the shard layout (<id[:2]>/<id[2:]>/...);
// any non-shard (root-level) paths are folded into the first checkpoint commit
// so the resulting commit count matches one-per-checkpoint, or stand alone when
// there are no checkpoint shards at all.
func planCheckpointCommits(localEntries, remoteEntries map[string]object.TreeEntry) []checkpointCommitPlan {
	byID := map[string][]string{}
	var rootPaths []string
	for path, localEntry := range localEntries {
		if remoteEntry, ok := remoteEntries[path]; ok && remoteEntry.Hash == localEntry.Hash {
			continue // identical shard — already on the remote tip
		}
		if cid, ok := checkpointIDForPath(path); ok {
			byID[cid] = append(byID[cid], path)
		} else {
			rootPaths = append(rootPaths, path)
		}
	}
	if len(byID) == 0 && len(rootPaths) == 0 {
		return nil
	}

	ids := make([]string, 0, len(byID))
	for cid := range byID {
		ids = append(ids, cid)
	}
	sort.Strings(ids)

	if len(ids) == 0 {
		sort.Strings(rootPaths)
		return []checkpointCommitPlan{{message: "Update metadata branch", paths: rootPaths}}
	}

	plans := make([]checkpointCommitPlan, 0, len(ids))
	for i, cid := range ids {
		paths := byID[cid]
		if i == 0 {
			paths = append(paths, rootPaths...) // fold rare root changes into the first commit
		}
		sort.Strings(paths)
		plans = append(plans, checkpointCommitPlan{message: "Checkpoint: " + cid, paths: paths})
	}
	return plans
}

// checkpointIDForPath returns the checkpoint id a shard path belongs to, parsed
// from the <id[:2]>/<id[2:]>/... layout, and whether the path is a shard path.
func checkpointIDForPath(path string) (string, bool) {
	parts := strings.Split(path, "/")
	if len(parts) < 3 || len(parts[0]) != 2 {
		return "", false
	}
	cid, err := id.NewCheckpointID(parts[0] + parts[1])
	if err != nil {
		return "", false
	}
	return cid.String(), true
}

// commitTreeHash returns the tree hash of the commit at h.
func commitTreeHash(repo *git.Repository, h plumbing.Hash) (plumbing.Hash, error) {
	commit, err := repo.CommitObject(h)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("read commit %s: %w", h, err)
	}
	return commit.TreeHash, nil
}

// commitMergedTree writes a single commit holding treeHash, parented on parent,
// authored/committed by the repo identity, with the given subject.
func commitMergedTree(ctx context.Context, repo *git.Repository, treeHash, parent plumbing.Hash, message string) (plumbing.Hash, error) {
	name, email := GetGitAuthorFromRepo(repo)
	sig := object.Signature{Name: name, Email: email, When: time.Now()}
	commit := &object.Commit{
		TreeHash:     treeHash,
		ParentHashes: []plumbing.Hash{parent},
		Author:       sig,
		Committer:    sig,
		Message:      message + "\n",
	}
	checkpoint.SignCommitBestEffort(ctx, commit)

	obj := repo.Storer.NewEncodedObject()
	if err := commit.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("encode merge commit: %w", err)
	}
	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("store merge commit: %w", err)
	}
	return hash, nil
}

