	return currentTip, nil
}

// checkpointCommitPlan is one commit to replay onto the remote tip: the paths
// whose local entries to apply and the commit subject to use.
type checkpointCommitPlan struct {
	message string
	paths   []string
}

// planCheckpointCommits diffs the local tip against the remote tip and groups
// the local-only/differing paths into per-checkpoint commits. Paths are grouped
// by the checkpoint id parsed from the shard layout (<id[:2]>/<id[2:]>/...);
// any non-shard (root-level) paths are folded into the first checkpoint commit
// so the resulting commit count matches one-per-checkpoint, or stand alone when
// there are no checkpoint shards at all.
func planCheckpointCommits(localEntries, remoteEntries map[string]object.TreeEntry) []checkpointCommitPlan {
	byID := map[string][]string{}
	var rootPaths []string
	for path, localEntry := range localEntries {
		if remoteEntry, ok := remoteEntries[path]; ok && remoteEntry.Hash == localEntry.Hash {
			continue // identical shard — already on the remote tip
		}
		if cid, ok := checkpointIDForPath(path); ok {
			byID[cid] = append(byID[cid], path)
		} else {
			rootPaths = append(rootPaths, path)
		}
	}
	if len(byID) == 0 && len(rootPaths) == 0 {
		return nil
	}

	ids := make([]string, 0, len(byID))
	for cid := range byID {
		ids = append(ids, cid)
	}
	sort.Strings(ids)

	if len(ids) == 0 {
		sort.Strings(rootPaths)
		return []checkpointCommitPlan{{message: "Update metadata branch", paths: rootPaths}}
	}

	plans := make([]checkpointCommitPlan, 0, len(ids))
	for i, cid := range ids {
		paths := byID[cid]
		if i == 0 {
			paths = append(paths, rootPaths...) // fold rare root changes into the first commit
		}
		sort.Strings(paths)
		plans = append(plans, checkpointCommitPlan{message: "Checkpoint: " + cid, paths: paths})
	}
	return plans
}

// checkpointIDForPath returns the checkpoint id a shard path belongs to, parsed
// from the <id[:2]>/<id[2:]>/... layout, and whether the path is a shard path.
func checkpointIDForPath(path string) (string, bool) {
	parts := strings.Split(path, "/")
	if len(parts) < 3 || len(parts[0]) != 2 {
		return "", false
	}
	cid, err := id.NewCheckpointID(parts[0] + parts[1])
	if err != nil {
		return "", false
	}
	return cid.String(), true
}

// commitTreeHash returns the tree hash of the commit at h.
func commitTreeHash(repo *git.Repository, h plumbing.Hash) (plumbing.Hash, error) {
	commit, err := repo.CommitObject(h)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("read commit %s: %w", h, err)
	}
	return commit.TreeHash, nil
}

// commitMergedTree writes a single commit holding treeHash, parented on parent,
// authored/committed by the repo identity, with the given subject.
func commitMergedTree(ctx context.Context, repo *git.Repository, treeHash, parent plumbing.Hash, message string) (plumbing.Hash, error) {
	name, email := GetGitAuthorFromRepo(repo)
	sig := object.Signature{Name: name, Email: email, When: time.Now()}
	commit := &object.Commit{
		TreeHash:     treeHash,
		ParentHashes: []plumbing.Hash{parent},
		Author:       sig,
		Committer:    sig,
		Message:      message + "\n",
	}
	checkpoint.SignCommitBestEffort(ctx, commit)

	obj := repo.Storer.NewEncodedObject()
	if err := commit.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("encode merge commit: %w", err)
	}
	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("store merge commit: %w", err)
	}
	return hash, nil
}

